xml.Script:
        Color1 := '202020'; // Black
        Color2 := 'A02020'; // Red

        Colors[0] := Color2;
        Colors[1] := Color1;
        Colors[2] := Color2;
        Colors[3] := Color1;
        Colors[4] := Color2;
        Colors[5] := Color1;

        W := 0.5;

        N := 13;
        WD := 2 * W / (N + 4);
        for i := 0 to N - 2 do
            D[i] := WD * (-N / 2 + 1 + i);

        WX := W;
        WY := W;
        WZ := W;
        DWX :=-W * 0.08;
        DWY := W * 0.04;
        DWZ :=-W * 0.12;
